{"title":"赛车水平圆弯道向心力探究","domain":"circular","model_js":"'use strict';
(function () {
  var TAU = Math.PI * 2;

  function num(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : d; }

  function sample(input) {
    input = input || {};
    var sc = input.scenario || {};
    var mode = typeof sc.mode === 'string' ? sc.mode : 'uniform';
    var G = num(sc.G_n_m2_kg2, 6.6743e-11);
    var M = num(sc.central_mass_kg, 0);
    var g = num(sc.g_m_s2, 9.8);
    var m = Math.max(num(sc.mass_kg, 1), 0);
    var r = Math.max(num(sc.radius_m, 1), 1e-12);
    var vIn = Math.max(num(sc.speed_m_s, 0), 0);

    var angles = input.angles_rad;
    if (!Array.isArray(angles) || angles.length === 0) {
      angles = [0, Math.PI / 2, Math.PI, 3 * Math.PI / 2];
    }

    var i;
    var isOrbit = (mode === 'orbit');
    var isVertical = (mode === 'vertical_string');

    var vOrbit = isOrbit ? Math.sqrt(Math.max(G * M / r, 0)) : 0;
    var vBase = isOrbit ? vOrbit : vIn;

    // vertical_string: angle 0 = lowest point, vBase is speed at the bottom
    function v2At(th) {
      var c = Math.cos(th);
      var s = Math.sin(th);
      if (!isVertical) return vBase * vBase;
      return vBase * vBase - 2 * g * r * (1 - c);
    }

    var states = [];
    for (i = 0; i < angles.length; i++) {
      var th = num(angles[i], 0);
      var c = Math.cos(th);
      var s = Math.sin(th);
      var v2 = v2At(th);
      var blocked = isVertical && v2 < 0;
      var v = Math.sqrt(Math.max(v2, 0));
      var aR = v * v / r; // inward centripetal acceleration
      var aT = isVertical ? -g * s : 0; // tangential acceleration along +theta

      var x, y, ux, uy, tx, ty;
      if (isVertical) {
        x = r * s; y = -r * c;
        ux = s; uy = -c;   // outward radial unit vector
        tx = c; ty = s;    // unit vector along +theta
      } else {
        x = r * c; y = r * s;
        ux = c; uy = s;
        tx = -s; ty = c;
      }
      var ax = -aR * ux + aT * tx;
      var ay = -aR * uy + aT * ty;

      var radialForce = m * aR;
      var tension;
      if (isOrbit) tension = 0;
      else if (isVertical) tension = m * aR + m * g * c;
      else tension = radialForce;
      if (blocked) { tension = 0; }

      var ke = 0.5 * m * v * v;
      var pe = isVertical ? m * g * r * (1 - c) : 0;

      states.push({
        angle_rad: th,
        x_m: x,
        y_m: y,
        speed_m_s: v,
        ax_m_s2: ax,
        ay_m_s2: ay,
        radial_force_n: radialForce,
        tension_n: tension,
        kinetic_j: ke,
        potential_j: pe,
        mechanical_j: ke + pe
      });
    }

    var period;
    if (!isVertical) {
      period = (vBase > 0) ? TAU * r / vBase : null;
    } else {
      var N = 200000;
      var dth = TAU / N;
      var ok = true;
      var sum = 0;
      for (i = 0; i < N; i++) {
        var tm = (i + 0.5) * dth;
        var vv2 = v2At(tm);
        if (vv2 <= 0) { ok = false; break; }
        sum += r * dth / Math.sqrt(vv2);
      }
      period = ok ? sum : null;
    }

    var events = {
      period_s: period,
      centripetal_acceleration_m_s2: (vBase * vBase) / r
    };
    if (isVertical) {
      events.critical_top_speed_m_s = Math.sqrt(g * r);
      events.critical_bottom_speed_m_s = Math.sqrt(5 * g * r);
    }

    return { states: states, events: events };
  }

  globalThis.coursewareModel = Object.freeze({ sample: sample });
})();"}
